describe('Print Filtered Table View', () => {
  beforeEach(() => {
    cy.visit('/table-list');
  });

  it('should print a filtered table view successfully', () => {
    // Filter the table by selecting a specific category
    cy.get('[data-testid="category-filter"]').click();
    cy.get('[data-testid="filter-option-electronics"]').click();

    // Verify the table is filtered
    cy.get('[data-testid="table-row"]').should('have.length.greaterThan', 0);
    cy.get('[data-testid="table-row"]').first().should('contain', 'Electronics');

    // Click the print button
    cy.get('[data-testid="print-button"]').click();

    // Verify print dialog appears
    cy.get('[data-testid="print-dialog"]').should('be.visible');
    cy.get('[data-testid="print-dialog"]').should('contain', 'Print');

    // Verify print preview shows filtered data
    cy.get('[data-testid="print-preview"]').should('be.visible');
    cy.get('[data-testid="print-preview"]').should('contain', 'Electronics');

    // Close print dialog
    cy.get('[data-testid="close-print-button"]').click();

    // Verify print dialog is closed
    cy.get('[data-testid="print-dialog"]').should('not.exist');
  });

  it('should handle printing an empty filtered table view', () => {
    // Filter the table to an empty category
    cy.get('[data-testid="category-filter"]').click();
    cy.get('[data-testid="filter-option-empty"]').click();

    // Verify table is empty
    cy.get('[data-testid="table-row"]').should('not.exist');
    cy.get('[data-testid="empty-state-message"]').should('be.visible');
    cy.get('[data-testid="empty-state-message"]').should('contain', 'No results found');

    // Attempt to print
    cy.get('[data-testid="print-button"]').click();

    // Verify print dialog appears with empty state
    cy.get('[data-testid="print-dialog"]').should('be.visible');
    cy.get('[data-testid="print-dialog"]').should('contain', 'No results found');

    // Verify print preview shows empty state
    cy.get('[data-testid="print-preview"]').should('be.visible');
    cy.get('[data-testid="print-preview"]').should('contain', 'No results found');

    // Close print dialog
    cy.get('[data-testid="close-print-button"]').click();

    // Verify print dialog is closed
    cy.get('[data-testid="print-dialog"]').should('not.exist');
  });
});
